import { NodePackageInstallTask } from '@angular-devkit/schematics/tasks/index.js';
import { addPackageJsonDependency, detectPackageManager, getPackageJsonDependency, NodeDependencyType, } from './dependencies.utils.js';
import { findNestCliConfigPath, readJsonFile } from './nest-cli-config.util.js';
export const RSPACK_DEV_DEPENDENCIES = {
    '@rspack/core': '^2.1.10',
    'fork-ts-checker-webpack-plugin': '^9.1.0',
    'tsconfig-paths-webpack-plugin': '^4.2.0',
    'webpack-node-externals': '^3.0.0',
};
const RSPACK_PEER_RANGES = {
    '@rspack/core': '^1.7.7 || ^2.1.10',
};
function builderType(compilerOptions) {
    const builder = compilerOptions?.builder;
    return typeof builder === 'string' ? builder : builder?.type;
}
export function usesRspackBuilder(tree) {
    const configPath = findNestCliConfigPath(tree);
    const config = configPath ? readJsonFile(tree, configPath) : null;
    if (!config) {
        return false;
    }
    const projects = Object.values(config.projects ?? {});
    return [config, ...projects].some((target) => builderType(target?.compilerOptions) === 'rspack');
}
function isJavaScriptProject(tree, language) {
    if (language === 'js') {
        return true;
    }
    const configPath = findNestCliConfigPath(tree);
    return ((configPath ? readJsonFile(tree, configPath) : null)?.language === 'js');
}
function canSatisfy(current, required) {
    const major = (range) => /^[\^~=]?v?(\d+)(?:\.[\dx*]+){0,2}(?:-[\w.]+)?$/.exec(range.trim())?.[1];
    const currentMajor = major(current);
    return (currentMajor === undefined ||
        required.split('||').some((range) => major(range) === currentMajor));
}
export function addMissingRspackDependencies(tree) {
    const result = { added: [], incompatible: [] };
    if (!tree.exists('package.json')) {
        return result;
    }
    for (const [name, version] of Object.entries(RSPACK_DEV_DEPENDENCIES)) {
        const existing = getPackageJsonDependency(tree, name);
        const required = RSPACK_PEER_RANGES[name] ?? version;
        if (!existing) {
            addPackageJsonDependency(tree, {
                type: NodeDependencyType.Dev,
                name,
                version,
            });
            result.added.push(name);
        }
        else if (!canSatisfy(existing.version, required)) {
            result.incompatible.push({ name, current: existing.version, required });
        }
    }
    return result;
}
export function joinNames(names) {
    return names.length > 1
        ? `${names.slice(0, -1).join(', ')} and ${names[names.length - 1]}`
        : names.join('');
}
export function addRspackDependencies(options = {}) {
    return (tree, context) => {
        if (isJavaScriptProject(tree, options.language) ||
            !usesRspackBuilder(tree)) {
            return tree;
        }
        const { added, incompatible } = addMissingRspackDependencies(tree);
        for (const { name, current, required } of incompatible) {
            context.logger.warn(`${name}@"${current}" does not match the rspack builder's required range "${required}"; left unchanged. Update it before running "nest build".`);
        }
        if (added.length > 0) {
            const packageManager = detectPackageManager(tree);
            context.logger.info(`Added ${joinNames(added)} for the rspack builder; running "${packageManager} install"`);
            context.addTask(new NodePackageInstallTask({ packageManager }));
        }
        return tree;
    };
}
